			// 날짜 계산 후 문자열 처리
			function dayText(params, id){
			    
			    // 전체 일수를 365를 뺀 나머지 값
			    var yearCalc = Number(params / 365);
			    var monthDay, year, month, day = 0;
			    
			    // 1년이상 또는 1년 이하 계산                    
			    if(yearCalc >= 1){
			        // 365를 뺀 값이 1이 넘으면 추가 값이 있으므로 월 계산을 위해 저장
			        year = String(yearCalc).substring(0, 1);
			        monthDay = params % 365;
			    }else{
			        // 1년 미만인 경우 연을 계산하지않고 전부 월 계산 값에 넣는다.
			        year = 0;
			        monthDay = params;
			    }
			    
			    // 남은 개월수 계산 및 남은 일자 계산
			    var monthCalc = Number(monthDay / 30);
			    if(monthCalc >= 1){                            
			        month = String(monthCalc).substring(0, 1);
			        day = monthDay % 30;                            
			    }else{
			        
			        month = 0;
			        day = monthDay;                            
			    }
			    
			    // 문자열 생성
			    var text = "";
			    if(year > 0){
			        text += year + "년";
			    }
			    
			    if(month > 0){
			        text += " " + month + "개월";
			    }
			    
			    if(day > 0){
			        text += " " + day + "일 (" + params + "일)";
			    }
			    
			    /** @type cpr.controls.Output */
			    var obj = app.lookup(id);
			    obj.value = text;
			    obj.redraw();
			    
			}

